package com.kovian.finance.liability.api; import com.kovian.finance.liability.domain.*; import com.kovian.finance.liability.repository.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*; @RestController @RequestMapping("/api/v1/liabilities") public class LiabilityController {final FinancialLiabilityRepository repo; LiabilityController(FinancialLiabilityRepository r){repo=r;} record Request(UUID ownerId,String name,String liabilityType,BigDecimal amount){} @PostMapping public FinancialLiability create(@RequestBody Request r){return repo.save(new FinancialLiability(r.ownerId(),r.name(),r.liabilityType(),r.amount()));} @GetMapping public List<FinancialLiability> list(@RequestParam UUID ownerId){return repo.findByOwnerIdAndActiveTrue(ownerId);} @PatchMapping("/{id}") public void update(@PathVariable UUID id,@RequestParam UUID ownerId,@RequestBody BigDecimal amount){repo.findById(id).filter(x->x.getOwnerId().equals(ownerId)).orElseThrow().updateAmount(amount);}}